<?php
declare(strict_types=1);
require_once __DIR__.'/includes/auth.php'; require_login();
require_once __DIR__.'/includes/functions.php';
$pdo=db();$from=(string)($_GET['from']??date('Y-m-d',strtotime('-7 days')));$to=(string)($_GET['to']??date('Y-m-d'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-d',strtotime('-7 days'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');$start=$from.' 00:00:00';$end=$to.' 23:59:59';
$metric=function(string $sql)use($pdo,$start,$end){$s=$pdo->prepare($sql);$s->execute([$start,$end]);return(int)$s->fetchColumn();};
$events=$metric('SELECT COUNT(*) FROM events WHERE created_at BETWEEN ? AND ?');$alerts=$metric('SELECT COUNT(*) FROM alerts WHERE created_at BETWEEN ? AND ?');$incidents=$metric('SELECT COUNT(*) FROM incidents WHERE created_at BETWEEN ? AND ?');$critical=$metric("SELECT COUNT(*) FROM alerts WHERE severity='critical' AND created_at BETWEEN ? AND ?");
$rules=$pdo->prepare('SELECT r.name,r.severity,COUNT(a.id) total FROM rules r JOIN alerts a ON a.rule_id=r.id WHERE a.created_at BETWEEN ? AND ? GROUP BY r.id,r.name,r.severity ORDER BY total DESC');$rules->execute([$start,$end]);$rules=$rules->fetchAll();
$incs=$pdo->prepare("SELECT i.id,i.title,i.severity,i.status,i.created_at,i.resolution,e.source_key,e.ip_address FROM incidents i LEFT JOIN alerts a ON a.id=i.alert_id LEFT JOIN events e ON e.id=a.event_id WHERE i.created_at BETWEEN ? AND ? ORDER BY i.id DESC LIMIT 100");$incs->execute([$start,$end]);$incs=$incs->fetchAll();
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte SecureWatch <?= esc($from) ?> - <?= esc($to) ?></title><style>body{font-family:Arial,sans-serif;color:#17202a;margin:34px}h1{margin-bottom:0}small,.muted{color:#657786}.metrics{display:flex;gap:12px;margin:24px 0}.m{border:1px solid #ccd6dd;border-radius:8px;padding:12px;min-width:130px}.m strong{display:block;font-size:25px;margin-top:5px}table{width:100%;border-collapse:collapse;margin:12px 0 26px}th,td{border-bottom:1px solid #dde4e8;text-align:left;padding:8px;font-size:12px}th{background:#edf4f7}.badge{font-weight:bold}footer{margin-top:30px;border-top:1px solid #ddd;padding-top:10px;font-size:11px;color:#777}@media print{.no-print{display:none}body{margin:15mm}}</style></head><body>
<button class="no-print" data-print>Imprimir / Guardar como PDF</button><h1>SecureWatch SIEM</h1><div class="muted">Reporte de seguridad y auditoría · <?= esc($from) ?> al <?= esc($to) ?></div>
<div class="metrics"><div class="m">Eventos<strong><?= $events ?></strong></div><div class="m">Alertas<strong><?= $alerts ?></strong></div><div class="m">Críticas<strong><?= $critical ?></strong></div><div class="m">Incidentes<strong><?= $incidents ?></strong></div></div>
<h2>Principales detecciones</h2><table><thead><tr><th>Regla</th><th>Severidad</th><th>Total</th></tr></thead><tbody><?php foreach($rules as $r): ?><tr><td><?= esc($r['name']) ?></td><td><?= esc(strtoupper($r['severity'])) ?></td><td><?= (int)$r['total'] ?></td></tr><?php endforeach; ?></tbody></table>
<h2>Incidentes del período</h2><table><thead><tr><th>ID</th><th>Incidente</th><th>Fuente / IP</th><th>Severidad</th><th>Estado</th><th>Resolución</th></tr></thead><tbody><?php foreach($incs as $i): ?><tr><td>#<?= (int)$i['id'] ?></td><td><?= esc($i['title']) ?></td><td><?= esc($i['source_key']?:'Interno') ?> / <?= esc($i['ip_address']?:'—') ?></td><td><?= esc(strtoupper($i['severity'])) ?></td><td><?= esc(human_status($i['status'])) ?></td><td><?= esc($i['resolution']?:'—') ?></td></tr><?php endforeach; ?></tbody></table>
<script src="assets/js/app.js"></script><footer>Generado por SecureWatch SIEM el <?= esc(date('d/m/Y H:i:s')) ?>. Este reporte conserva trazabilidad de eventos, alertas e incidentes registrados en el sistema.</footer></body></html>
